```

3. `source/index.ts`:
   a. Add a top-level helper near the other validators (`validateTimeout`/`validateLimit`/`validateRateLimit`, lines 45-78):
```ts
function validatePriority(priority: number) {
    if (typeof priority !== 'number' || !Number.isFinite(priority)) {
        throw new TypeError(`Expected \`priority\` to be a finite number, got \`${priority}\` (${typeof priority})`);
    }
}
```
   Replace the first `if` block in the existing `setPriority` with a call to `validatePriority(priority);` and keep the rest of `setPriority` byte-identical.
   b. Add `setPriorities` immediately after `setPriority`. Logic:
```ts
setPriorities(updates: ReadonlyArray<{id: string; priority: number}>) {
	if (updates.length === 0) {
		return;
	}

	for (const {id, priority} of updates) {
		validatePriority(priority);

		let exists = false;
		for (const waitingTask of this.#waitingTasks) {
			if (waitingTask.id === id) {
				exists = true;
				break;
			}
		}

		if (!exists) {
			throw new ReferenceError(`No promise function with the id "${id}" exists in the queue.`);
		}
	}

	if (typeof this.#queue.setPriorities === 'function') {
		this.#queue.setPriorities(updates);

		for (const {id, priority} of updates) {
			for (const waitingTask of this.#waitingTasks) {
				if (waitingTask.id === id) {
					waitingTask.priority = priority;
					break;
				}
			}
		}
	} else {
		for (const {id, priority} of updates) {
			this.setPriority(id, priority);
		}
	}
}
```
This validates the whole batch (finite priority TypeError, then unknown/running-id ReferenceError against `#waitingTasks`) before touching `#queue` or `#waitingTasks`. Duplicate ids are validated against the same waiting entry and applied in order, so last wins. Empty batch returns before any work.

