{"path": "benchmark_tests/set-priorities.test.ts", "content": "import {test} from 'node:test';
import assert from 'node:assert/strict';
import pDefer from 'p-defer';
import PQueue from '../source/index.js';
import PriorityQueue from '../source/priority-queue.js';
import {FifoQueue} from '../test/helpers.js';

const createRun = (value: string) => async () => value;

test('PriorityQueue setPriorities reorders items and applies duplicate ids in update order', () => {
	const queue = new PriorityQueue();
	const first = createRun('first');
	const second = createRun('second');
	const third = createRun('third');

	queue.enqueue(first, {id: 'first', priority: 3});
	queue.enqueue(second, {id: 'second', priority: 2});
	queue.enqueue(third, {id: 'third', priority: 1});

	queue.setPriorities([
		{id: 'first', priority: 0},
		{id: 'second', priority: -1},
		{id: 'first', priority: 4},
	]);

	assert.deepEqual(
		[queue.dequeue(), queue.dequeue(), queue.dequeue()],
		[first, third, second],
	);
	assert.equal(queue.dequeue(), undefined);
});

test('PriorityQueue setPriorities no-ops on an empty batch', () => {
	const queue = new PriorityQueue();
	const first = createRun('first');
	const second = createRun('second');

	queue.enqueue(first, {id: 'first', priority: 1});
	queue.enqueue(second, {id: 'second', priority: 0});

	queue.setPriorities([]);

	assert.deepEqual([queue.dequeue(), queue.dequeue()], [first, second]);
	assert.equal(queue.dequeue(), undefined);
});

test('PriorityQueue setPriorities validates every id before mutating', () => {
	const queue = new PriorityQueue();
	const first = createRun('first');
	const second = createRun('second');

	queue.enqueue(first, {id: 'first', priority: 2});
	queue.enqueue(second, {id: 'second', priority: 1});

	assert.throws(() => {
		queue.setPriorities([
			{id: 'first', priority: 5},
			{id: 'missing', priority: 3},
		]);
	}, {
		name: 'ReferenceError',
		message: 'No promise function with the id "missing" exists in the queue.',
	});

	assert.deepEqual([queue.dequeue(), queue.dequeue()], [first, second]);
	assert.equal(queue.dequeue(), undefined);
});

test('PQueue setPriorities rejects nonfinite priorities before changing anything', async () => {
	const invalidPriorities = [NaN, Infinity, -Infinity, '1', undefined];

	for (const priority of invalidPriorities) {
		const queue = new PQueue({concurrency: 1, autoStart: false});
		const order: string[] = [];
		const observed: number[] = [];
		const enqueue = (id: string, initialPriority: number) => {
			queue.add(async () => {
				order.push(id);
				observed.push(queue.runningTasks[0]?.priority ?? -1);
			}, {id, priority: initialPriority});
		};

		enqueue('first', 2);
		enqueue('second', 1);

